        "**BiPAP is for obesity hypoventilation, overlap syndrome and CPAP intolerance at high pressures** - the expiratory drop makes exhaling easier. [AASM 2023]",
        "**Modafinil is reserved for residual sleepiness despite documented CPAP adherence** - prescribing it earlier masks under-treatment. [AASM 2023]",
