        "**About 90% of these patients also have OSA**, so the two are assessed together rather than sequentially. [AASM 2023]",
        "**Suspect it when the venous bicarbonate is raised** - metabolic compensation for chronic hypercapnia is the cheapest screening test available. [AASM 2023]",
        "**Treat with positive airway pressure plus aggressive weight loss, because untreated mortality is high** - CPAP if severe OSA coexists, otherwise BiPAP. [AASM 2023]",
