        "**Counsel documented sleepiness against driving until treated**, and involve the employer where a commercial licence is held. [AASM 2023]",
        "**Re-assess with the Epworth score and the CPAP download before clearing the patient to drive** - self-report alone is not enough. [AASM 2023]",
